13	declare_lint_rule! {
14	    /// Enforce the use of Array.prototype.find() over Array.prototype.filter() followed by [0] when looking for a single result.
15	    ///
16	    /// When searching for the first item in an array matching a condition, it may be tempting to use code like `arr.filter(x => x > 0)[0]`.
17	    /// However, it is simpler to use `Array.prototype.find()` instead, `arr.find(x => x > 0)`, which also returns the first entry matching a condition.
18	    /// Because the `.find()` only needs to execute the callback until it finds a match, it's also more efficient.
19	    ///
20	    /// ## Examples
21	    ///
22	    /// ### Invalid
23	    ///
24	    /// ```ts,expect_diagnostic,file=invalid.ts
25	    /// [1, 2, 3].filter(x => x > 1)[0];
26	    /// ```
27	    ///
28	    /// ```ts,expect_diagnostic,file=invalid2.ts
29	    /// [1, 2, 3].filter(x => x > 1).at(0);
30	    /// ```
31	    ///
32	    /// ### Valid
33	    ///
34	    /// ```ts,file=valid.ts
35	    /// [1, 2, 3].find(x => x > 1);
36	    /// ```
37	    ///
38	    pub UseFind {
39	        version: "2.3.6",
40	        name: "useFind",
41	        language: "js",
42	        recommended: false,
43	        sources: &[RuleSource::EslintTypeScript("prefer-find").same()],
44	        domains: &[RuleDomain::Types],
45	    }
46	}
