13	    ///
14	    /// String#match is defined to work the same as RegExp#exec when the regular expression does not include the g flag.
15	    /// Keeping to consistently using one of the two can help improve code readability.
16	    ///
17	    /// RegExp#exec may also be slightly faster than String#match; this is the reason to choose it as the preferred usage.
18	    ///
19	    /// ## Examples
20	    ///
21	    /// ### Invalid
22	    ///
23	    /// ```ts,file=invalid.ts,expect_diagnostic
24	    /// 'something'.match(/thing/);
25	    /// ```
26	    ///
27	    /// ### Valid
28	    ///
29	    /// ```ts,file=valid.ts
30	    /// /thing/.exec('something');
31	    /// ```
32	    ///
33	    pub UseRegexpExec {
34	        version: "2.3.9",
35	        name: "useRegexpExec",
36	        language: "js",
37	        recommended: false,
38	        sources: &[RuleSource::EslintTypeScript("prefer-regexp-exec").same(), RuleSource::EslintRegexp("prefer-regexp-exec").same()],
